    /**
     * Selects a collection of WfInstancia objects pre-filled with their WfActividadTransicion objects.
     * @param      Criteria  $criteria
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return array           Array of WfInstancia objects.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinWfActividadTransicion(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(WfInstanciaPeer::DATABASE_NAME);
        }

        WfInstanciaPeer::addSelectColumns($criteria);
        $startcol = WfInstanciaPeer::NUM_HYDRATE_COLUMNS;
        WfActividadTransicionPeer::addSelectColumns($criteria);

        $criteria->addJoin(WfInstanciaPeer::WFACTIVIDADTRANSICION_ID, WfActividadTransicionPeer::WFACTIVIDADTRANSICION_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseWfInstanciaPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = WfInstanciaPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = WfInstanciaPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {

                $cls = WfInstanciaPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                WfInstanciaPeer::addInstanceToPool($obj1, $key1);
            } // if $obj1 already loaded

            $key2 = WfActividadTransicionPeer::getPrimaryKeyHashFromRow($row, $startcol);
            if ($key2 !== null) {
                $obj2 = WfActividadTransicionPeer::getInstanceFromPool($key2);
                if (!$obj2) {

                    $cls = WfActividadTransicionPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    WfActividadTransicionPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (WfInstancia) to $obj2 (WfActividadTransicion)
                $obj2->addWfInstancia($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


